const app=document.getElementById('app');
const KEYS={settings:'gps-v7-settings',history:'gps-v7-history',compass:'gps-v7-compass-history'};
const S={view:'home',mode:'short',questions:[],i:0,answers:{},unknown:0,result:null,saving:false,rotation:0,selectedCompass:null,dragging:false,commMode:'home',commCategory:null,selectedMessage:null,phrase:[],visualScreen:'intro',visualRound:0,visualBatches:[],visualShortlist:[],visualRoundChoice:null,visualFinal:[],visualResult:null};
const get=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(f))}catch{return f}};
const set=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function setView(v){S.view=v;document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render();window.scrollTo(0,0)}
function render(){try{({home,gps,question,result,visual,compass,communicate,history,method}[S.view]||home)()}catch(e){console.error(e);app.innerHTML=`<section class="card"><p class="eyebrow">ERREUR</p><h2>Un problème d’affichage est survenu.</h2><button class="primary" onclick="setView('home')">Revenir à l’accueil</button></section>`}}
function home(){
 app.innerHTML=`<section class="card"><p class="eyebrow">VERSION 8</p><h2>Comprendre, reconnaître et communiquer.</h2><p>Quatre outils complémentaires, utilisables séparément selon votre disponibilité du moment.</p><div class="grid">
 <button class="module" onclick="setView('gps')"><strong>◎ Questionnaire GPS</strong><small>Observer le corps et obtenir des hypothèses.</small></button>
 <button class="module" onclick="setView('visual')"><strong>▧ Mon humeur en images</strong><small>Choisir trois photographies sans devoir répondre à des questions.</small></button>
 <button class="module" onclick="setView('compass')"><strong>↗ Boussole émotionnelle</strong><small>Placer manuellement l’aiguille sur une émotion.</small></button>
 <button class="module" onclick="setView('communicate')"><strong>▣ Communiquer maintenant</strong><small>Montrer ou vocaliser un besoin quand parler est difficile.</small></button>
 <button class="module" onclick="setView('history')"><strong>▤ Historique</strong><small>Retrouver les questionnaires, choix visuels et émotions confirmées.</small></button></div>
 <div class="notice">Les outils proposent des repères. Ils ne posent aucun diagnostic.</div><button class="secondary" onclick="setView('method')">Méthode et limites</button></section>`}
function gps(){app.innerHTML=`<section class="card"><p class="eyebrow">QUESTIONNAIRE</p><h2>Choisir un parcours</h2><div class="grid"><button class="choice" data-mode="short"><strong>Parcours court</strong><small>3 à 5 minutes.</small></button><button class="choice" data-mode="full"><strong>Parcours complet</strong><small>7 à 10 minutes.</small></button></div><div class="notice">Une question à la fois. Oui, Non ou Difficile à dire.</div></section>`;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>startGps(b.dataset.mode))}
function startGps(mode){S.mode=mode;S.questions=QUESTIONS.filter(q=>q.safety||mode==='full'||SHORT_IDS.has(q.id));S.i=0;S.answers={};S.unknown=0;S.result=null;S.view='question';render()}
function question(){const q=S.questions[S.i],p=Math.round(100*S.i/S.questions.length);app.innerHTML=`<div class="progress-label"><span>Question ${S.i+1} sur ${S.questions.length}</span><span>${p} %</span></div><div class="progress"><div style="width:${p}%"></div></div><section class="card qcard"><span class="zone">${esc(q.stage)}</span><h2 class="question">${esc(q.q)}</h2><p class="muted">${esc(q.help||'Répondez seulement pour maintenant.')}</p><div class="answers"><button class="answer yes" data-a="yes">Oui</button><button class="answer no" data-a="no">Non</button><button class="answer unsure" data-a="unsure">Difficile à dire</button></div><div id="confirm"></div><button class="secondary" onclick="setView('gps')">Quitter</button></section>`;document.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>answer(b.dataset.a))}
function answer(a){if(S.saving)return;S.saving=true;const q=S.questions[S.i];S.answers[q.id]=a;if(a==='unsure')S.unknown++;if(q.safety&&a==='yes')return safetyStop();document.getElementById('confirm').innerHTML='<div class="confirmation">✓ Réponse notée</div>';setTimeout(()=>{S.i++;S.saving=false;if(S.i>=S.questions.length){S.result=calculate();S.view='result'}render()},220)}
function safetyStop(){S.saving=false;app.innerHTML=`<section class="card"><p class="eyebrow">SÉCURITÉ</p><h2>J’arrête le questionnaire.</h2><div class="notice danger">Une forte douleur thoracique, un malaise ou une difficulté respiratoire importante doivent être évalués médicalement.</div><p>En cas d’urgence en France : 15 ou 112.</p><button class="primary" onclick="setView('home')">Retour</button></section>`}
function calculate(){const support={},possible={},cues={};Object.keys(STATES).forEach(k=>{support[k]=0;possible[k]=0;cues[k]=[]});S.questions.forEach(q=>{if(!q.w)return;const a=S.answers[q.id];Object.entries(q.w).forEach(([k,w])=>{if(a!=='unsure')possible[k]+=w;if(a==='yes'){support[k]+=w;cues[k].push(q.q)}})});let arr=Object.keys(STATES).map(k=>({key:k,ratio:possible[k]?support[k]/possible[k]:0,raw:support[k],cues:cues[k]})).sort((a,b)=>b.ratio-a.ratio),sum=arr.reduce((s,x)=>s+x.ratio,0);let flo=arr.map(x=>({...x,pct:Math.floor(sum?100*x.ratio/sum:0)})),rem=100-flo.reduce((s,x)=>s+x.pct,0);arr.map((x,i)=>({i,f:(sum?100*x.ratio/sum:0)-Math.floor(sum?100*x.ratio/sum:0)})).sort((a,b)=>b.f-a.f).slice(0,rem).forEach(x=>flo[x.i].pct++);return{mix:flo,confidence:Math.round(100*(S.questions.length-S.unknown)/S.questions.length)}}
function result(){const v=S.result.mix.filter(x=>x.pct>0).slice(0,6),m=v[0]&&v[0].raw>0?v[0]:null;app.innerHTML=`<section class="card"><p class="eyebrow">PANORAMA</p><h2>${m?esc(STATES[m.key].name):'État non déterminé'}</h2><p>Réponses claires : <strong>${S.result.confidence} %</strong></p><div class="mix">${v.map(x=>`<div class="mixrow"><strong>${esc(STATES[x.key].name)}</strong><div class="bar"><div style="width:${x.pct}%"></div></div><span class="pct">${x.pct}%</span></div>`).join('')}</div><div class="notice">Compatibilités relatives, pas mesure biologique d’une émotion.</div>${m?`<p>${esc(STATES[m.key].function)}</p><div>${STATES[m.key].needs.map(n=>`<span class="tag">${esc(n)}</span>`).join('')}</div>`:''}<label class="field">Intensité<input id="intensity" type="range" min="0" max="10" value="5"></label><label class="field">Contexte<input id="context" type="text"></label><button class="primary" id="saveResult">Enregistrer</button><button class="secondary" onclick="setView('compass')">Explorer avec la boussole</button></section>`;document.getElementById('saveResult').onclick=()=>{const h=get(KEYS.history,[]);h.unshift({type:'gps',date:new Date().toISOString(),intensity:+intensity.value,context:context.value,mix:S.result.mix.map(x=>({key:x.key,pct:x.pct}))});set(KEYS.history,h.slice(0,250));setView('history')}}
function compass(){const settings=get(KEYS.settings,{snap:true});app.innerHTML=`<section class="card"><p class="eyebrow">BOUSSOLE ÉMOTIONNELLE</p><h2 style="text-align:center">Quelle émotion est la plus proche ?</h2><p class="muted" style="text-align:center">Faites glisser l’aiguille ou touchez une émotion.</p><div class="compass-shell" id="compass" tabindex="0"><div class="compass-face"></div><div class="axis-label top">ÉNERGIE FORTE</div><div class="axis-label bottom">ÉNERGIE FAIBLE</div><div class="axis-label left">DÉSAGRÉABLE</div><div class="axis-label right">AGRÉABLE</div>${COMPASS.map(e=>`<button class="emotion-node ${S.selectedCompass?.id===e.id?'active':''}" data-id="${e.id}" style="--angle:${e.angle}deg"><span class="icon">${STATES[e.id].icon}</span><strong>${esc(STATES[e.id].name)}</strong></button>`).join('')}<div class="needle-wrap" style="--rotation:${S.rotation}deg"><div class="needle"></div></div><div class="center-label">TOURNER<br>L’AIGUILLE</div></div><div id="compassSelection">${compassSelection()}</div></section>`;bindCompass(settings)}
function compassSelection(){if(!S.selectedCompass)return `<div class="selection"><p style="text-align:center">Aucune émotion sélectionnée.</p></div>`;const e=S.selectedCompass,s=STATES[e.id];return `<div class="selection"><div class="selection-head"><div class="selection-icon">${s.icon}</div><div><p class="eyebrow">HYPOTHÈSE CHOISIE</p><h2>${esc(s.name)}</h2></div></div><div class="badges"><span class="badge">${esc(e.family)}</span><span class="badge">${esc(e.activation)}</span></div><p>${esc(s.function)}</p><h3>Besoins possibles</h3><div class="needs">${s.needs.slice(0,3).map(n=>`<div class="need">${esc(n)}</div>`).join('')}</div><h3>Mots voisins</h3><div class="badges">${e.nuances.map(n=>`<span class="badge">${esc(n)}</span>`).join('')}</div><button class="primary" id="confirmCompass">Confirmer ce choix</button><button class="secondary" id="clearCompass">Effacer</button></div>`}
function bindCompass(settings){const c=document.getElementById('compass');const move=(x,y)=>{const r=c.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let d=Math.atan2(y-cy,x-cx)*180/Math.PI+90;if(d<0)d+=360;chooseCompass(d,settings.snap!==false,false)};c.onpointerdown=e=>{S.dragging=true;c.setPointerCapture(e.pointerId);move(e.clientX,e.clientY)};c.onpointermove=e=>{if(S.dragging)move(e.clientX,e.clientY)};c.onpointerup=e=>{S.dragging=false;c.releasePointerCapture(e.pointerId);render()};c.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();chooseCompass(S.rotation+(e.key==='ArrowRight'?6:-6),settings.snap!==false,true)};document.querySelectorAll('.emotion-node').forEach(b=>b.onclick=e=>{e.stopPropagation();const emo=COMPASS.find(x=>x.id===b.dataset.id);S.rotation=emo.angle;S.selectedCompass=emo;render()});document.getElementById('confirmCompass')?.addEventListener('click',()=>{const h=get(KEYS.history,[]);h.unshift({type:'compass',date:new Date().toISOString(),emotion:S.selectedCompass.id});set(KEYS.history,h.slice(0,250));setView('history')});document.getElementById('clearCompass')?.addEventListener('click',()=>{S.selectedCompass=null;render()})}
function chooseCompass(deg,snap,rerender){S.rotation=((deg%360)+360)%360;const nearest=[...COMPASS].sort((a,b)=>dist(S.rotation,a.angle)-dist(S.rotation,b.angle))[0];S.selectedCompass=nearest;if(snap)S.rotation=nearest.angle;if(rerender)render();else{document.querySelector('.needle-wrap')?.style.setProperty('--rotation',`${S.rotation}deg`);const a=document.getElementById('compassSelection');if(a)a.innerHTML=compassSelection()}}
function dist(a,b){const d=Math.abs(a-b)%360;return Math.min(d,360-d)}
function communicate(){if(S.selectedMessage)return communicationMessage();if(S.commMode==='home')return communicationHome();if(S.commMode==='category')return communicationCategory();if(S.commMode==='compose')return communicationCompose()}
function communicationHome(){app.innerHTML=`<section class="card"><p class="eyebrow">COMMUNIQUER MAINTENANT</p><h2>Parler est difficile maintenant</h2><p>Touchez le message que vous voulez montrer.</p><div class="grid">${COMM_IMMEDIATE.map(commCard).join('')}</div><button class="secondary" id="needsBtn">Mes besoins</button><button class="secondary" id="composeBtn">Composer une phrase</button></section>`;bindCommCards();needsBtn.onclick=()=>{S.commMode='category';S.commCategory=null;render()};composeBtn.onclick=()=>{S.commMode='compose';render()}}
function commCard(m){return `<button class="message-card" data-message="${esc(m.text)}" data-icon="${esc(m.icon)}"><span class="message-icon">${esc(m.icon)}</span><span>${esc(m.text)}</span></button>`}
function bindCommCards(){document.querySelectorAll('[data-message]').forEach(b=>b.onclick=()=>{S.selectedMessage={text:b.dataset.message,icon:b.dataset.icon};render()})}
function communicationCategory(){if(!S.commCategory){app.innerHTML=`<section class="card"><button class="secondary" onclick="S.commMode='home';render()">← Retour</button><p class="eyebrow">MES BESOINS</p><div class="category-grid">${Object.entries(COMM_CATEGORIES).map(([k,c])=>`<button class="category" data-cat="${k}"><strong>${c.icon} ${esc(c.label)}</strong><small>Ouvrir les messages</small></button>`).join('')}</div></section>`;document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{S.commCategory=b.dataset.cat;render()});return}const c=COMM_CATEGORIES[S.commCategory];app.innerHTML=`<section class="card"><button class="secondary" onclick="S.commCategory=null;render()">← Catégories</button><p class="eyebrow">${esc(c.label)}</p><div class="grid">${c.items.map(commCard).join('')}</div></section>`;bindCommCards()}
function communicationMessage(){const m=S.selectedMessage;app.innerHTML=`<section class="card"><button class="secondary" id="backMessage">← Retour</button><div class="selected-message"><div class="big-icon">${esc(m.icon)}</div><div class="big-text">${esc(m.text)}</div></div><div class="action-row"><button class="primary" id="showBig">Montrer en grand</button><button class="secondary" id="speak">Faire parler</button></div></section>`;backMessage.onclick=()=>{S.selectedMessage=null;render()};showBig.onclick=()=>fullscreen(m);speak.onclick=()=>speakText(m.text)}
function fullscreen(m){const d=document.createElement('div');d.className='fullscreen-message';d.innerHTML=`<div class="fs-icon">${esc(m.icon)}</div><div class="fs-text">${esc(m.text)}</div><button class="primary">Fermer</button>`;document.body.appendChild(d);d.querySelector('button').onclick=()=>d.remove()}
function speakText(text){const s=get(KEYS.settings,{confirmSpeech:true});if(s.confirmSpeech!==false&&!confirm(`Faire lire : « ${text} » ?`))return;if(!('speechSynthesis'in window))return alert('Synthèse vocale indisponible.');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='fr-FR';speechSynthesis.speak(u)}
function communicationCompose(){const bank=['Je','veux','ne veux pas','besoin de','attendre','partir','silence','aide','eau','seul','maintenant','plus tard'];app.innerHTML=`<section class="card"><button class="secondary" onclick="S.commMode='home';render()">← Retour</button><p class="eyebrow">COMPOSER</p><div class="phrase-builder">${S.phrase.length?S.phrase.map(w=>`<span class="word-chip">${esc(w)}</span>`).join(''):'<span class="muted">Touchez des mots.</span>'}</div><div class="word-bank">${bank.map(w=>`<button data-word="${esc(w)}">${esc(w)}</button>`).join('')}</div><label class="field">Ou écrire<textarea id="freeText"></textarea></label><div class="action-row"><button class="secondary" id="clearPhrase">Effacer</button><button class="primary" id="usePhrase">Utiliser</button></div></section>`;document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{S.phrase.push(b.dataset.word);render()});clearPhrase.onclick=()=>{S.phrase=[];render()};usePhrase.onclick=()=>{const t=freeText.value.trim()||S.phrase.join(' ');if(!t)return;S.selectedMessage={icon:'💬',text:t};render()}}

function visual(){
 if(S.visualScreen==='intro')return visualIntro();
 if(S.visualScreen==='round')return visualRound();
 if(S.visualScreen==='final')return visualFinal();
 if(S.visualScreen==='result')return visualResult();
}
function visualShuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
function visualBuildBatches(){
 const byMod={};['human','environment','object','sensory'].forEach(m=>byMod[m]=visualShuffle(VISUAL_CORPUS.filter(x=>x.modality===m)));
 S.visualBatches=Array.from({length:10},(_,i)=>visualShuffle(['human','environment','object','sensory'].map(m=>byMod[m][i])));
}
function visualReset(){
 S.visualScreen='intro';S.visualRound=0;S.visualBatches=[];S.visualShortlist=[];S.visualRoundChoice=null;S.visualFinal=[];S.visualResult=null;render()
}
function visualIntro(){
 app.innerHTML=`<section class="card"><p class="eyebrow">GPS ÉMOTIONNEL VISUEL</p><h2>Choisissez les images qui ressemblent à votre humeur actuelle.</h2><p class="muted">Vous verrez dix séries de quatre photographies. Dans chaque série, retenez une image ou passez. À la fin, choisissez vos trois images les plus importantes.</p><div class="visual-steps"><div class="visual-step">1<br>Observer</div><div class="visual-step">2<br>Choisir trois images</div><div class="visual-step">3<br>Voir les hypothèses</div></div><div class="notice">Il n’y a pas de bonne réponse. Choisissez ce que l’image vous fait ressentir, pas ce qu’elle est censée représenter.</div><button class="primary" id="visualStart">Commencer</button><button class="secondary" onclick="setView('home')">Retour à l’accueil</button></section>`;
 visualStart.onclick=()=>{visualBuildBatches();S.visualRound=0;S.visualShortlist=[];S.visualRoundChoice=null;S.visualFinal=[];S.visualResult=null;S.visualScreen='round';render()}
}
function visualCard(x,selected=false){
 return `<button class="photo-card ${selected?'selected':''}" data-photo-id="${x.id}" aria-pressed="${selected}"><img src="${x.file}" alt="${esc(x.description)}"><span class="caption">${esc(x.description)}</span><span class="sub">${esc(x.modalityLabel)}</span>${selected?'<span class="check-mark">✓</span>':''}</button>`
}
function visualRound(){
 const batch=S.visualBatches[S.visualRound],pct=Math.round((S.visualRound/10)*100);
 app.innerHTML=`<div class="progress-label"><span>Série ${S.visualRound+1} sur 10</span><span>${pct} %</span></div><div class="progress"><div style="width:${pct}%"></div></div><section class="card"><p class="eyebrow">LAQUELLE VOUS RESSEMBLE LE PLUS ?</p><h2>Retenez une image, ou passez cette série.</h2>${S.visualShortlist.length?`<div class="visual-shortlist">${S.visualShortlist.map(x=>`<div class="visual-thumb"><img src="${x.file}" alt=""><span>${esc(x.description)}</span></div>`).join('')}</div>`:''}<div class="photo-grid">${batch.map(x=>visualCard(x,S.visualRoundChoice===x.id)).join('')}</div><div class="visual-actions"><button class="secondary" id="visualSkip">Aucune de ces images</button><button class="primary" id="visualNext" ${S.visualRoundChoice?'':'disabled'}>Retenir et continuer</button></div></section>`;
 document.querySelectorAll('[data-photo-id]').forEach(b=>b.onclick=()=>{S.visualRoundChoice=+b.dataset.photoId;render()});
 visualSkip.onclick=()=>visualAdvance(false);visualNext.onclick=()=>visualAdvance(true)
}
function visualAdvance(keep){
 if(keep&&S.visualRoundChoice){const p=VISUAL_CORPUS.find(x=>x.id===S.visualRoundChoice);if(!S.visualShortlist.some(x=>x.id===p.id))S.visualShortlist.push(p)}
 S.visualRoundChoice=null;S.visualRound++;
 if(S.visualRound>=10)S.visualScreen='final';
 render()
}
function visualFinal(){
 const enough=S.visualShortlist.length>=3;
 app.innerHTML=`<section class="card"><p class="eyebrow">CHOIX FINAL</p><h2>Choisissez exactement trois images.</h2><p><span class="visual-counter">${S.visualFinal.length} sur 3 sélectionnées</span></p>${enough?`<div class="photo-grid">${S.visualShortlist.map(x=>visualCard(x,S.visualFinal.includes(x.id))).join('')}</div>`:`<div class="notice">Vous avez retenu seulement ${S.visualShortlist.length} image(s). Recommencez et passez moins de séries afin d’en sélectionner au moins trois.</div>`}<button class="primary" id="visualAnalyse" ${S.visualFinal.length===3?'':'disabled'}>Analyser mes trois choix</button><button class="secondary" id="visualRestart">Recommencer</button></section>`;
 document.querySelectorAll('[data-photo-id]').forEach(b=>b.onclick=()=>{const id=+b.dataset.photoId,i=S.visualFinal.indexOf(id);if(i>=0)S.visualFinal.splice(i,1);else if(S.visualFinal.length<3)S.visualFinal.push(id);render()});
 visualAnalyse.onclick=visualAnalyse;visualRestart.onclick=visualReset
}
function visualAnalyse(){
 const sums=Object.fromEntries(Object.keys(STATES).map(k=>[k,0]));
 S.visualFinal.map(id=>VISUAL_CORPUS.find(x=>x.id===id)).forEach(p=>Object.entries(p.weights).forEach(([k,v])=>sums[k]+=v));
 const total=Object.values(sums).reduce((a,b)=>a+b,0);
 const raw=Object.entries(sums).map(([key,v])=>({key,exact:v/total*100}));
 const scores=raw.map(x=>({key:x.key,pct:Math.floor(x.exact)})).sort((a,b)=>b.pct-a.pct);
 let rem=100-scores.reduce((a,b)=>a+b.pct,0);
 raw.sort((a,b)=>(b.exact-Math.floor(b.exact))-(a.exact-Math.floor(a.exact))).slice(0,rem).forEach(x=>scores.find(y=>y.key===x.key).pct++);
 scores.sort((a,b)=>b.pct-a.pct);
 const margin=scores[0].pct-scores[1].pct;
 S.visualResult={scores,coherence:margin>=25?'forte':margin>=12?'modérée':'faible',margin};
 S.visualScreen='result';render()
}
function visualResult(){
 const top=S.visualResult.scores[0],second=S.visualResult.scores.slice(1,3),st=STATES[top.key];
 app.innerHTML=`<section class="card"><div class="visual-result"><p class="eyebrow">HYPOTHÈSE PRINCIPALE</p><div class="visual-result-icon">${st.icon}</div><h2 class="visual-dominant">${esc(st.name)}</h2><p>${esc(st.function)}</p><span class="visual-counter">Cohérence ${S.visualResult.coherence}</span></div><h3>Vos trois images</h3><div class="visual-selected-strip">${S.visualFinal.map(id=>{const x=VISUAL_CORPUS.find(p=>p.id===id);return `<img src="${x.file}" alt="${esc(x.description)}">`}).join('')}</div><div class="mix">${S.visualResult.scores.filter(x=>x.pct>=3).slice(0,6).map(x=>`<div class="mixrow"><strong>${esc(STATES[x.key].name)}</strong><div class="bar"><div style="width:${x.pct}%"></div></div><span class="pct">${x.pct}%</span></div>`).join('')}</div><div class="notice safe"><strong>Autres hypothèses :</strong> ${second.map(x=>`${STATES[x.key].name} (${x.pct} %)`).join(' · ')}</div><h3>Besoins possibles</h3><div>${st.needs.map(n=>`<span class="tag">${esc(n)}</span>`).join('')}</div><div class="notice">Le résultat décrit les associations intégrées au corpus. Il ne prouve pas que vous ressentez cette émotion.</div><button class="primary" id="visualConfirm">Ce résultat me correspond</button><button class="secondary" id="visualCorrect">Corriger avec la boussole</button><button class="secondary" id="visualAgain">Refaire le parcours</button></section>`;
 visualConfirm.onclick=()=>{const h=get(KEYS.history,[]);h.unshift({type:'visual',date:new Date().toISOString(),emotion:top.key,coherence:S.visualResult.coherence,images:[...S.visualFinal],scores:S.visualResult.scores});set(KEYS.history,h.slice(0,250));setView('history')};
 visualCorrect.onclick=()=>{S.selectedCompass=COMPASS.find(x=>x.id===top.key)||null;S.rotation=S.selectedCompass?.angle||0;setView('compass')};
 visualAgain.onclick=visualReset
}

function history(){
 const h=get(KEYS.history,[]);
 const typeLabel=x=>x.type==='gps'?'Questionnaire':x.type==='visual'?'Photos':'Boussole';
 const detail=x=>x.type==='gps'?x.mix.filter(y=>y.pct>0).slice(0,4).map(y=>`${STATES[y.key].name} ${y.pct}%`).join(' · '):x.type==='visual'?`${STATES[x.emotion]?.name||''} · cohérence ${x.coherence}`:STATES[x.emotion]?.name||'';
 app.innerHTML=`<section class="card"><p class="eyebrow">HISTORIQUE</p><h2>Enregistrements</h2>${h.length?h.map((x,i)=>`<article class="history-item"><strong>${typeLabel(x)}</strong><p>${detail(x)}</p>${x.type==='visual'&&x.images?.length?`<div class="visual-selected-strip">${x.images.map(id=>{const p=VISUAL_CORPUS.find(v=>v.id===id);return p?`<img src="${p.file}" alt="${esc(p.description)}">`:''}).join('')}</div>`:''}<small>${new Date(x.date).toLocaleString('fr-FR')}</small><button class="secondary delete" data-i="${i}">Supprimer</button></article>`).join(''):'<p>Aucun enregistrement.</p>'}${h.length?'<button class="secondary" id="clearAll">Tout effacer</button>':''}</section>`;
 document.querySelectorAll('.delete').forEach(b=>b.onclick=()=>{const l=get(KEYS.history,[]);l.splice(+b.dataset.i,1);set(KEYS.history,l);render()});
 document.getElementById('clearAll')?.addEventListener('click',()=>{if(confirm('Tout effacer ?')){set(KEYS.history,[]);render()}})
}
function method(){app.innerHTML=`<section class="card"><button class="secondary" onclick="setView('home')">← Retour</button><p class="eyebrow">MÉTHODE</p><h2>Quatre fonctions distinctes</h2><div class="notice"><strong>Questionnaire :</strong> transforme des observations corporelles et contextuelles en hypothèses probabilistes.</div><div class="notice"><strong>Photos :</strong> combine les profils pondérés de trois images choisies par l’utilisateur. Les pondérations devront être recalibrées par les tests.</div><div class="notice"><strong>Boussole :</strong> permet à l’utilisateur de choisir ou corriger lui-même l’émotion la plus proche.</div><div class="notice"><strong>Communication :</strong> permet de montrer ou vocaliser un message lorsque parler est difficile.</div><p>Aucun module ne pose de diagnostic. Une photographie n’a pas de signification émotionnelle universelle.</p></section>`}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>setView(b.dataset.view));
const dlg=document.getElementById('settingsDialog');settingsBtn.onclick=()=>{const s=get(KEYS.settings,{});fontSize.value=s.font||'normal';contrast.checked=!!s.contrast;motion.checked=!!s.motion;snapCompass.checked=s.snap!==false;confirmSpeech.checked=s.confirmSpeech!==false;dlg.showModal()};saveSettings.onclick=()=>{const s={font:fontSize.value,contrast:contrast.checked,motion:motion.checked,snap:snapCompass.checked,confirmSpeech:confirmSpeech.checked};set(KEYS.settings,s);applySettings(s);dlg.close()};function applySettings(s){document.body.classList.toggle('font-large',s.font==='large');document.body.classList.toggle('font-xlarge',s.font==='xlarge');document.body.classList.toggle('high-contrast',!!s.contrast);document.body.classList.toggle('reduce-motion',!!s.motion)}applySettings(get(KEYS.settings,{}));render();

if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))}
